<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
const props=defineProps<{phase?:string;compact?:boolean}>(),elapsed=ref(0)
const phases:Record<string,[string,string]>={preparing:['正在连接校园助手','已收到问题，正在准备回答'],context:['正在整理问题和资料','查找相关内容，为回答补充依据'],tools:['正在查询相关资料','资料到达后继续回答'],model:['正在生成回答','内容到达后会逐步显示'],retrying:['正在恢复回答','正在自动处理输出格式，请稍候'],finalizing:['正在整理回答','正在完成最后的校验']}
const copy=computed(()=>phases[props.phase||'']||['正在编排卡片','文字可以先阅读，卡片完成后会直接显示'])
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>elapsed.value++,1000)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>
